input.command:
ls -la package && python -I -c "
import pypdfium2 as pdfium,glob
for f in sorted(glob.glob('package/*.pdf')):
    d=pdfium.PdfDocument(f)
    sizes={}
    for i in range(len(d)):
        w,h=d[i].get_size(); k=(round(w/72*25.4),round(h/72*25.4)); sizes.setdefault(k,[]).append(i+1)
    print(f,len(d),{k:(v if len(v)<8 else len(v)) for k,v in sizes.items()})
"

